import{_ as a,c as r,o as t,ae as i}from"./chunks/framework.BtEkjhVd.js";const u=JSON.parse('{"title":"User Manual for fAIr","description":"","frontmatter":{},"headers":[],"relativePath":"User-Manual-for-fAIr.md","filePath":"User-Manual-for-fAIr.md"}'),o={name:"User-Manual-for-fAIr.md"};function n(l,e,s,d,p,h){return t(),r("div",null,e[0]||(e[0]=[i('<h1 id="user-manual-for-fair" tabindex="-1">User Manual for fAIr <a class="header-anchor" href="#user-manual-for-fair" aria-label="Permalink to &quot;User Manual for fAIr&quot;">​</a></h1><p>Welcome! This manual is your step-by-step guide to getting started with fAIr, the AI-assisted mapping platform from the Humanitarian OpenStreetMap Team (HOT).</p><hr><h2 id="table-of-contents" tabindex="-1">Table of Contents <a class="header-anchor" href="#table-of-contents" aria-label="Permalink to &quot;Table of Contents&quot;">​</a></h2><ul><li><a href="#prerequisites">Prerequisites</a></li><li><a href="#video-tutorials">Video Tutorials</a></li><li><a href="#creating-a-project-in-fair">Creating a Project in fAIr</a></li><li><a href="#starting-mapping-in-your-project">Starting Mapping in Your Project</a></li><li><a href="#editing-model-predictions">Editing Model Predictions</a></li><li><a href="#help-and-support">Help and Support</a></li><li><a href="#thank-you">Thank You</a></li></ul><hr><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><ul><li>Stable internet connection</li><li>Basic mapping knowledge (<a href="https://tasks.hotosm.org/learn/map" target="_blank" rel="noreferrer">learn more</a>)</li><li>Basic understanding of AI datasets and models</li><li>Account on <a href="https://fair-dev.hotosm.org/" target="_blank" rel="noreferrer">fAIr</a></li></ul><hr><h2 id="video-tutorials" tabindex="-1">Video Tutorials <a class="header-anchor" href="#video-tutorials" aria-label="Permalink to &quot;Video Tutorials&quot;">​</a></h2><p>Watch our step-by-step video guides:</p><ul><li><a href="https://github.com/hotosm/fAIr/assets/97789856/47121891-b21a-43c0-bb60-1e03f5222c10" target="_blank" rel="noreferrer">Getting Started</a></li><li><a href="https://github.com/hotosm/fAIr/assets/97789856/d7d86a6f-e492-4169-8443-d9924cb10e54" target="_blank" rel="noreferrer">Creating Datasets</a></li><li><a href="https://github.com/hotosm/fAIr/assets/97789856/f68def4f-6b0b-4870-801c-0fac16713249" target="_blank" rel="noreferrer">Training Models</a></li><li><a href="https://github.com/hotosm/fAIr/assets/97789856/3da0771d-0346-4042-9049-4f321c27ba8d" target="_blank" rel="noreferrer">Mapping with Predictions</a></li><li><a href="https://github.com/hotosm/fAIr/assets/97789856/1e2efaf0-f0c2-4331-a290-566434db5db3" target="_blank" rel="noreferrer">Feedback and Validation</a></li><li>...and more on our <a href="https://github.com/hotosm/fAIr" target="_blank" rel="noreferrer">GitHub</a></li></ul><hr><h2 id="creating-a-project-in-fair" tabindex="-1">Creating a Project in fAIr <a class="header-anchor" href="#creating-a-project-in-fair" aria-label="Permalink to &quot;Creating a Project in fAIr&quot;">​</a></h2><ol><li><strong>Log in to <a href="https://fair-dev.hotosm.org/" target="_blank" rel="noreferrer">fAIr</a>.</strong></li><li>Click <strong>Start Creating Dataset</strong>.</li><li>Click <strong>Create New</strong> to make a new dataset.</li><li>Name your dataset and click <strong>Create Training Dataset</strong>.</li><li>Open <a href="https://openaerialmap.org/" target="_blank" rel="noreferrer">OpenAerialMap</a> in a new tab, find a suitable drone image, and copy its TMS URL.</li><li>Paste the TMS URL into the Open Aerial Imagery tab in fAIr.</li><li>Zoom to your image layer for visualization.</li><li>Use the map tools to draw your Area of Interest (AOI).</li><li>Click <strong>Fetch OSM Data</strong> to import existing building footprints for your AOI.</li><li>Zoom in and review the imported buildings for accuracy.</li><li>Edit and align building labels as needed for best training results.</li><li>Upload your label fixes to OSM.</li><li>Back in fAIr, fetch updated OSM labels for your AOI.</li><li>On your dataset page, click <strong>View Models</strong> and then <strong>Create New</strong> to start a new model.</li><li>Fill in model metadata and click <strong>Create AI Model</strong>.</li><li>On the model page, submit a new training job with your chosen parameters.</li><li>Monitor training progress and review accuracy graphs.</li><li>Once satisfied, click <strong>Publish Training</strong> to make your model available for mapping.</li></ol><hr><h2 id="starting-mapping-in-your-project" tabindex="-1">Starting Mapping in Your Project <a class="header-anchor" href="#starting-mapping-in-your-project" aria-label="Permalink to &quot;Starting Mapping in Your Project&quot;">​</a></h2><ol><li>On the model page, click <strong>Start Mapping</strong> next to your published training.</li><li>Zoom to your area of interest and click <strong>Detect</strong> to run predictions.</li><li>Review the AI-generated predictions on the map.</li><li>Edit, accept, or discard predictions as needed.</li><li>Push your validated results to OSM or export for further editing.</li></ol><hr><h2 id="editing-model-predictions" tabindex="-1">Editing Model Predictions <a class="header-anchor" href="#editing-model-predictions" aria-label="Permalink to &quot;Editing Model Predictions&quot;">​</a></h2><ol><li>Select a model and click <strong>Start Mapping</strong> to view predictions.</li><li>Zoom in and review the predicted features.</li><li>Accept or discard parts of the prediction, then re-run if needed.</li><li>After making changes, click <strong>Submit my Feedback</strong>.</li><li>All feedback is reviewed and validated by the project manager.</li></ol><blockquote><p><strong>Note:</strong> Each &quot;task&quot; refers to a section of the map outlined with dotted lines and a number tag.</p></blockquote><hr><h2 id="help-and-support" tabindex="-1">Help and Support <a class="header-anchor" href="#help-and-support" aria-label="Permalink to &quot;Help and Support&quot;">​</a></h2><p>If you need help:</p><ul><li>Check the <a href="./FAQ.html">FAQs</a></li><li>Join our <a href="https://slack.hotosm.org" target="_blank" rel="noreferrer">Slack channel</a></li><li>Open an issue on <a href="https://github.com/hotosm/fAIr/issues" target="_blank" rel="noreferrer">GitHub</a></li></ul><hr><h2 id="thank-you" tabindex="-1">Thank You <a class="header-anchor" href="#thank-you" aria-label="Permalink to &quot;Thank You&quot;">​</a></h2><p>Thank you for joining the fAIr community!<br> Your mapping efforts help create detailed, up-to-date maps that support crisis response, infrastructure planning, and community resilience worldwide.</p><p>By mapping with fAIr, you’re part of a global network of volunteers using open data and AI to make a positive impact.<br> Explore projects, join tasks, and connect with fellow mappers. Your contributions are invaluable!</p><p><strong>Happy mapping!</strong></p><p><em>The fAIr Team</em></p>',32)]))}const f=a(o,[["render",n]]);export{u as __pageData,f as default};
